size_t objectSlot(uint32_t role){return role>=1&&role<=5?size_t(role-1):NONE;}
tc::Phase phase(d4vr_tcs_adapter*a,uint32_t api){if(a->nextCase){if(a->caseOrdinal>=8)bad(a);else ++a->caseOrdinal;a->nextCase=false;}return {a->caseOrdinal,api};}
